 private static String messageSequence(String data){if(data==null)return "0";java.util.regex.Matcher m=java.util.regex.Pattern.compile("\"seq\":([0-9]+)").matcher(data.substring(0,Math.min(100,data.length())));return m.find()?m.group(1):"0";}
 private void receive(String data,String origin,boolean mainFrame,androidx.webkit.JavaScriptReplyProxy reply){if(data!=null&&data.length()<=5000&&data.startsWith("{\"kind\":\"location\"")){try{if(closed||web==null||!VintedBrowserPolicy.allowedMessage(origin,mainFrame,data.getBytes(StandardCharsets.UTF_8).length))return;String url=new JSONObject(data).optString("url");if(VintedBrowserPolicy.allowedPage(url)&&samePage(url,web.getUrl())&&!samePage(url,navigationUrl)){resetPage(url);loading=false;pageFailed=false;bindPage();refreshStatus();}}catch(Exception ignored){}return;}if(closed||!accepting||data==null||data.length()>128*1024||web==null||!VintedBrowserPolicy.allowedPage(navigationUrl)){rejected.incrementAndGet();reply.postMessage("paused:"+messageSequence(data));return;}int bytes=data.getBytes(StandardCharsets.UTF_8).length;if(!VintedBrowserPolicy.allowedMessage(origin,mainFrame,bytes)){rejected.incrementAndGet();return;}final long generation=captureGeneration,acceptedPageToken=pageGeneration;final String acceptedPageUrl=navigationUrl;try{ingest.execute(()->{boolean persisted=parse(data,generation,acceptedPageUrl,acceptedPageToken);runOnUiThread(()->{if(!closed)reply.postMessage((persisted?"ready:":"retry:")+messageSequence(data));});});}catch(java.util.concurrent.RejectedExecutionException error){rejected.incrementAndGet();reply.postMessage("retry:"+messageSequence(data));}}
 private boolean parse(String data,long generation,String acceptedPageUrl,long acceptedPageToken){try{
  java.util.List<JSONObject> captured=new java.util.ArrayList<>();JSONObject packet=new JSONObject(data);JSONArray incoming=packet.optJSONArray("items");if(packet.optInt("schema")!=1||incoming==null||incoming.length()>32){rejected.incrementAndGet();return true;}
  JSONObject page=packet.optJSONObject("page");if(page==null||!samePage(page.optString("url"),acceptedPageUrl)){rejected.incrementAndGet();return true;}
  synchronized(items){if(!samePage(page.optString("url"),acceptedPageUrl)||packet.optLong("pageToken",-1)!=acceptedPageToken)return true;boolean currentPage=acceptedPageToken==pageGeneration;if(currentPage){pageObserved=bound(page.optInt("observed"));pagePrices=bound(page.optInt("withPrice"));}for(int i=0;i<incoming.length();i++){JSONObject item=incoming.optJSONObject(i);if(item==null||!VintedBrowserPolicy.matchesItem(item.optString("url"),item.optString("id"))||item.optString("title").length()>600){rejected.incrementAndGet();continue;}String id=item.getString("id");if(currentPage&&!items.containsKey(id)&&items.size()>=500){dropped++;continue;}JSONObject clean=new JSONObject();for(String key:new String[]{"id","url","title","priceCents","protectedPriceCents","brand","condition","currency","sellerId","sellerName","description","language","publication","source","photos"}){Object value=item.opt(key);if(value==null||value==JSONObject.NULL)continue;if(value instanceof String&&((String)value).length()<=("description".equals(key)?2000:600))clean.put(key,value);else if(("priceCents".equals(key)||"protectedPriceCents".equals(key))&&value instanceof Number&&((Number)value).longValue()>0&&((Number)value).longValue()<=1000000000L)clean.put(key,value);else if("photos".equals(key)&&value instanceof JSONArray){JSONArray photos=new JSONArray();JSONArray source=(JSONArray)value;for(int n=0;n<Math.min(10,source.length());n++){String url=BrowserCapturePolicy.photo(source.optString(n));if(!url.isEmpty())photos.put(url);}if(photos.length()>0)clean.put(key,photos);}else if("publication".equals(key)&&value instanceof JSONObject){JSONObject p=(JSONObject)value;if(p.optString("raw").length()<=100&&p.optString("source").length()<=50)clean.put(key,new JSONObject().put("raw",p.optString("raw")).put("source",p.optString("source")));}}
   captured.add(clean);if(currentPage){JSONObject previous=items.get(id);if(previous!=null&&!previous.toString().equals(clean.toString()))updates++;items.put(id,clean);if("dom".equals(clean.optString("source")))domItems++;else jsonItems++;}}
   JSONObject stats=packet.optJSONObject("stats");if(currentPage&&stats!=null){dropped=Math.max(dropped,bound(stats.optInt("dropped")));unknownShapes=Math.max(unknownShapes,bound(stats.optInt("unknownShapes")));readErrors=Math.max(readErrors,bound(stats.optInt("readErrors")));oversized=Math.max(oversized,bound(stats.optInt("oversized")));}lastReport=reportLocked();}
  boolean persistedAll=true;intakeError="";if(!captured.isEmpty()){if(captureDatabase==null){captureDatabase=new DealDatabase(getApplicationContext());captureStore=new MarketStore(getApplicationContext(),captureDatabase);}for(JSONObject item:captured){try{long persisted=captureStore.captureBrowserItem(item,System.currentTimeMillis());if(persisted>0)synchronized(items){if(packet.optLong("pageToken",-1)==pageGeneration)persistedPageIds.add(item.optString("id"));} }catch(Exception failure){persistedAll=false;intakeError=failure.getClass().getSimpleName();}}sendBroadcast(new android.content.Intent(BrowserCapturePolicy.READY_ACTION).setPackage(getPackageName()));sendBroadcast(new android.content.Intent("it.vintedaffari.app.DEALS_UPDATED").setPackage(getPackageName()));}
  final boolean persisted=persistedAll;boolean complete=packet.optBoolean("complete");saveReport();runOnUiThread(()->{if(!closed){if(persisted&&complete&&!enabled&&packet.optLong("captureToken",-1)==captureGeneration&&generation==captureGeneration)accepting=false;refreshStatus();}});
 return persistedAll;}catch(Exception error){intakeError=error.getClass().getSimpleName();rejected.incrementAndGet();return false;}}
 private static boolean samePage(String a,String b){try{return Uri.parse(a).buildUpon().fragment(null).build().equals(Uri.parse(b).buildUpon().fragment(null).build());}catch(Exception e){return false;}}
 private static int bound(int n){return Math.max(0,Math.min(1000000,n));}
 private void observeRoute(Uri uri){if(uri==null||!"https".equals(uri.getScheme())||!("www.vinted.it".equals(uri.getHost())||"vinted.it".equals(uri.getHost())))return;String path=uri.getPath();if(path==null||!path.startsWith("/api/"))return;path=path.replaceAll("[0-9]+","{id}").replaceAll("[^a-zA-Z0-9/{}_\\-]","_");if(path.length()>160)path=path.substring(0,160);synchronized(routes){if(routes.size()<20)routes.add(path);}}
 private String reportLocked(){int price=0,seller=0,publication=0,language=0;for(JSONObject item:items.values()){if(item.has("priceCents"))price++;if(item.has("sellerId"))seller++;if(item.has("publication"))publication++;if(item.has("language"))language++;}String routeSummary;synchronized(routes){routeSummary=routes.toString();}return "build=browser-engine-intake-v1;app="+BuildConfig.VERSION_NAME+";state="+state+";mode="+mode+";features="+supported+";capture="+enabled+";scope=currentPage;page="+pageNumber()+";pageObserved="+pageObserved+";pagePrices="+pagePrices+";acquiredUnique="+items.size()+";updated="+updates+";price="+price+";seller="+seller+";publication="+publication+";language="+language+";jsonOrInitial="+jsonItems+";dom="+domItems+";dropped="+dropped+";unknownShapes="+unknownShapes+";readErrors="+readErrors+";oversized="+oversized+";rejected="+rejected.get()+";extraRequestsByCapture=0;networkScope=capturer-only;catalogWrites="+persistedPageIds.size()+";intakeScope=currentPage;intakeError="+intakeError+";sellerCoverage=partial;routes="+routeSummary;}
 private void saveReport(){String report; synchronized(items){report=reportLocked();lastReport=report;}getSharedPreferences("vinted_browser_experiment",MODE_PRIVATE).edit().putString("report",report).putLong("at",System.currentTimeMillis()).apply();}
 private int pageNumber(){try{return Math.max(1,Math.min(10,Integer.parseInt(Uri.parse(navigationUrl).getQueryParameter("page"))));}catch(Exception ignored){return 1;}}
 private void refreshStatus(){int size,price,saved; synchronized(items){size=items.size();saved=persistedPageIds.size();price=0;for(JSONObject x:items.values())if(x.has("priceCents"))price++;}if(status==null)return;toggle.setText(enabled?"Pausa":"Attiva");boolean catalog=Uri.parse(navigationUrl).getPath()!=null&&Uri.parse(navigationUrl).getPath().startsWith("/catalog");previous.setEnabled(supported&&catalog&&!loading&&!pageFailed&&pageNumber()>1);next.setEnabled(supported&&catalog&&!loading&&!pageFailed&&pageNumber()<10);previous.setAlpha(previous.isEnabled()?1f:.35f);next.setAlpha(next.isEnabled()?1f:.35f);capture.setEnabled(supported&&!loading&&!pageFailed&&web!=null);String minimum=Uri.parse(navigationUrl).getQueryParameter("price_from");String order=Uri.parse(navigationUrl).getQueryParameter("order");String orderLabel="newest_first".equals(order)?" · Nuovi":"price_low_to_high".equals(order)?" · Prezzo ↑":"price_high_to_low".equals(order)?" · Prezzo ↓":" · Rilevanza";String context=catalog?"Pagina "+pageNumber()+orderLabel+(minimum==null?"":" · da "+minimum+" €"):"Annuncio / venditore";status.setText(!supported?"Cattura non disponibile su questa WebView":rendererGone?"Browser interrotto":pageFailed||state.equals("PAGE_BLOCKED")?"Pagina non disponibile per la cattura":loading?"Caricamento…":context+"\n"+(enabled?"Cattura attiva":"Consultazione")+" · "+saved+" salvati · "+size+" acquisiti"+(!intakeError.isEmpty()?"\nSalvataggio da riprovare":"")+(dropped>0?"\nLimite cattura raggiunto · "+dropped+" eventi scartati":""));saveReport();}
 private void showReport(){String report;StringBuilder samples=new StringBuilder();synchronized(items){report=reportLocked();int n=0;for(JSONObject item:items.values()){if(n++>=8)break;samples.append("\n\n#").append(item.optString("id")).append(" · ").append(item.optString("title")).append("\n").append(item.optString("source")).append(" · ").append(item.opt("publication"));}}final String publicReport=report;TextView text=new TextView(this);text.setTextColor(TEXT);text.setTextSize(13);text.setPadding(dp(16),dp(16),dp(16),dp(16));text.setText("Gli annunci catturati vengono salvati per l’analisi locale. Prezzo e dati mancanti restano da acquisire; il sito può mostrare solo parte degli annunci del venditore.\n\n"+report+samples);text.setTextIsSelectable(true);ScrollView scroll=new ScrollView(this);scroll.addView(text);new AlertDialog.Builder(this).setTitle("Cattura browser · diagnostica").setView(scroll).setPositiveButton("Torna a Vinted",null).setNeutralButton("Copia report",(d,w)->{ClipboardManager clipboard=(ClipboardManager)getSystemService(CLIPBOARD_SERVICE);clipboard.setPrimaryClip(ClipData.newPlainText("Diagnostica browser",publicReport));}).show();}
